        null::varchar as AADHAAR_NUMBER,
        null::varchar as AADHAAR_VERIFICATION_STATUS,
        null::varchar as PAN_NUMBER,
        null::varchar as PAN_VERIFICATION_STATUS,
        null::varchar as PASSPORT_NUMBER,
        null::varchar as VOTER_ID_NUMBER,
        null::varchar as DRIVING_LICENCE_NUMBER,
        null::varchar as DRIVING_LICENCE_EXPIRY_DATE,
        null::varchar as GSTIN,
        null::varchar as CIN_NUMBER,
        null::varchar as TAN_NUMBER,
        null::varchar as NREGA_CARD_NUMBER,
        null::varchar as IDENTIFICATION_ISSUING_AUTHORITY,
        null::varchar as IDENTIFICATION_ISSUE_DATE,
        null::varchar as IDENTIFICATION_EXPIRY_DATE,
        null::varchar as IDENTIFICATION_VERIFIED_INDICATOR,
        null::varchar as OVD_CATEGORY,
        null::varchar as EIA_NUMBER,
        null::varchar as INSURANCE_REPOSITORY_NAME,
        CITIZENSHIP_ID as IDENTIFICATION_NUMBER,
        null::varchar as AGE_PROOF_TYPE,
        null::varchar as GST_REGISTRATION_STATUS,
        null::varchar as GST_TAXPAYER_TYPE,
        'MAXI_HLTH_UWR_VW_DATA_RELATIONS_PARTY' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_relp') }}
    where HUB_PARTY_K1__EMIT
    union all
    select
        md5(upper(HUB_PARTY_BK__K2)) as HUB_PARTY_HK,
        'AADHAAR_ENROLMENT' as IDENTIFICATION_TYPE_CODE,
        UID as AADHAAR_NUMBER,
        POA_AADHAR_CARD_STATUS as AADHAAR_VERIFICATION_STATUS,
        PAN_NUMBER as PAN_NUMBER,
        POI_PAN_CARD_STATUS as PAN_VERIFICATION_STATUS,
        PASSPORT_NUMBER as PASSPORT_NUMBER,
        VOTER_ID as VOTER_ID_NUMBER,
        DRIVING_LICENSE_NUMBER as DRIVING_LICENCE_NUMBER,
        DRIVING_LICENSE_EXPIRY_DATE as DRIVING_LICENCE_EXPIRY_DATE,
        PARTY_GST_NO as GSTIN,
        CIN_NUMBER as CIN_NUMBER,
        TAN_NUMBER as TAN_NUMBER,
        NREGA_JOB_CARD as NREGA_CARD_NUMBER,
        DRIVING_LICENSE_PLACE_OF_ISSUE as IDENTIFICATION_ISSUING_AUTHORITY,
        SEZ_REGISTRATION_DATE as IDENTIFICATION_ISSUE_DATE,
        SEZ_EXPIRY_DATE as IDENTIFICATION_EXPIRY_DATE,
        POI_DOCUMENT_STATUS as IDENTIFICATION_VERIFIED_INDICATOR,
        PROOF_OF_ADDRESS_SUBMITTED_FOR_CURRENT_PERMANENT_OVERSEAS_ADDRESSOTHERS as OVD_CATEGORY,
        EIA_NUMBER as EIA_NUMBER,
        INSURANCE_REPOSITORY_CODE as INSURANCE_REPOSITORY_NAME,
        VID as IDENTIFICATION_NUMBER,
        DOB_PROOF as AGE_PROOF_TYPE,
        GSTN_STATUS as GST_REGISTRATION_STATUS,
        TAXPAYER_TYPE as GST_TAXPAYER_TYPE,
        'MAXI_HLTH_UWR_VW_DATA_RELATIONS_PARTY_PARTY_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_relations_ppd_pv') }}
    where HUB_PARTY_K2__EMIT
)), hashed as (select *,
        case when AADHAAR_NUMBER is not null or AADHAAR_VERIFICATION_STATUS is not null or PAN_NUMBER is not null or PAN_VERIFICATION_STATUS is not null or PASSPORT_NUMBER is not null or VOTER_ID_NUMBER is not null or DRIVING_LICENCE_NUMBER is not null or DRIVING_LICENCE_EXPIRY_DATE is not null or GSTIN is not null or CIN_NUMBER is not null or TAN_NUMBER is not null or NREGA_CARD_NUMBER is not null or IDENTIFICATION_ISSUING_AUTHORITY is not null or IDENTIFICATION_ISSUE_DATE is not null or IDENTIFICATION_EXPIRY_DATE is not null or IDENTIFICATION_VERIFIED_INDICATOR is not null or OVD_CATEGORY is not null or EIA_NUMBER is not null or INSURANCE_REPOSITORY_NAME is not null or IDENTIFICATION_NUMBER is not null or AGE_PROOF_TYPE is not null or GST_REGISTRATION_STATUS is not null or GST_TAXPAYER_TYPE is not null
             then md5(upper(coalesce(AADHAAR_NUMBER::varchar,'') || '||' || coalesce(AADHAAR_VERIFICATION_STATUS::varchar,'') || '||' || coalesce(PAN_NUMBER::varchar,'') || '||' || coalesce(PAN_VERIFICATION_STATUS::varchar,'') || '||' || coalesce(PASSPORT_NUMBER::varchar,'') || '||' || coalesce(VOTER_ID_NUMBER::varchar,'') || '||' || coalesce(DRIVING_LICENCE_NUMBER::varchar,'') || '||' || coalesce(DRIVING_LICENCE_EXPIRY_DATE::varchar,'') || '||' || coalesce(GSTIN::varchar,'') || '||' || coalesce(CIN_NUMBER::varchar,'') || '||' || coalesce(TAN_NUMBER::varchar,'') || '||' || coalesce(NREGA_CARD_NUMBER::varchar,'') || '||' || coalesce(IDENTIFICATION_ISSUING_AUTHORITY::varchar,'') || '||' || coalesce(IDENTIFICATION_ISSUE_DATE::varchar,'') || '||' || coalesce(IDENTIFICATION_EXPIRY_DATE::varchar,'') || '||' || coalesce(IDENTIFICATION_VERIFIED_INDICATOR::varchar,'') || '||' || coalesce(OVD_CATEGORY::varchar,'') || '||' || coalesce(EIA_NUMBER::varchar,'') || '||' || coalesce(INSURANCE_REPOSITORY_NAME::varchar,'') || '||' || coalesce(IDENTIFICATION_NUMBER::varchar,'') || '||' || coalesce(AGE_PROOF_TYPE::varchar,'') || '||' || coalesce(GST_REGISTRATION_STATUS::varchar,'') || '||' || coalesce(GST_TAXPAYER_TYPE::varchar,'')))
        end as SAT_PARTY_IDENTIFICATION_HASHDIFF
    from feeders)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_IDENTIFICATION_HASHDIFF is not null
  and IDENTIFICATION_TYPE_CODE is not null
